// Calculate date range for the past week
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = oneWeekAgo.toISOString();
const until = now.toISOString();

const repo = $env.WEEKLY_SUMMARY_REPO || 'anthropics/claude-code';
const [owner, repoName] = repo.split('/');

return [{
  json: {
    owner,
    repo: repoName,
    since,
    until,
    fullRepo: repo
  }
}];

// Merge all GitHub data and filter PRs to only merged ones within the date range
const setVars = $('Set Variables').first().json;
const sinceDate = new Date(setVars.since);

// Commits
const commitsRaw = $('Fetch Commits').all();
const commits = commitsRaw
  .filter(item => item.json.sha)
  .map(item => ({
    message: (item.json.commit?.message || '').split('\n')[0],
    author: item.json.commit?.author?.name || 'Unknown',
    date: item.json.commit?.author?.date,
    url: item.json.html_url
  }));

// Closed Issues (filter out PRs, only real issues)
const issuesRaw = $('Fetch Closed Issues').all();
const issues = issuesRaw
  .filter(item => item.json.number && !item.json.pull_request)
  .filter(item => {
    const closed = new Date(item.json.closed_at);
    return closed >= sinceDate;
  })
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    url: item.json.html_url,
    labels: (item.json.labels || []).map(l => l.name)
  }));

// Merged PRs
const prsRaw = $('Fetch Merged PRs').all();
const prs = prsRaw
  .filter(item => item.json.merged_at)
  .filter(item => {
    const merged = new Date(item.json.merged_at);
    return merged >= sinceDate;
  })
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    url: item.json.html_url,
    author: item.json.user?.login || 'Unknown'
  }));

// Build summary stats
const stats = {
  totalCommits: commits.length,
  totalIssuesClosed: issues.length,
  totalPRsMerged: prs.length,
  uniqueAuthors: [...new Set(commits.map(c => c.author))].length,
  topContributors: Object.entries(
    commits.reduce((acc, c) => { acc[c.author] = (acc[c.author] || 0) + 1; return acc; }, {})
  ).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, count]) => ({ name, commits: count }))
};

return [{
  json: {
    repo: setVars.fullRepo,
    since: setVars.since,
    until: setVars.until,
    stats,
    commits: commits.slice(0, 50),
    issues,
    prs
  }
}];

