// Extract the text content from Claude's response
const response = $('Generate Summary with Claude').first().json;
let summary = '';

if (response.content && Array.isArray(response.content)) {
  summary = response.content.map(block => block.text || '').join('\n');
} else if (typeof response === 'string') {
  summary = response;
} else {
  summary = JSON.stringify(response);
}

return [{
  json: {
    summary,
    repo: $('Merge & Analyze Data').first().json.repo,
    since: $('Merge & Analyze Data').first().json.since,
    until: $('Merge & Analyze Data').first().json.until
  }
}];
